contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function taking the candidate new owner and a flag
    // `callAsOwner` indicates whether we attempt the transfer (always attempted) —
    // since this contract is the deployer of c, msg.sender for calls on c will be this contract.
    function run(address newOwner) public payable {
        // read the owner before the attempted transfer
        address ownerBefore = c.owner();

        // attempt transferOwnership and record whether it reverted
        bool reverted;
        try c.transferOwnership(newOwner) {
            reverted = false;
        } catch {
            reverted = true;
        }

        address ownerAfter = c.owner();

        // General rule:
        // If the call succeeded (did not revert) then ownerAfter must equal newOwner.
        // If the call reverted then ownerAfter must equal ownerBefore (no change).
        assert((!reverted && ownerAfter == newOwner) || (reverted && ownerAfter == ownerBefore));
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Test whether calling owned() succeeds exactly when this contract is the current owner.
    // We take a flag `makeCallerOwner`: if true, we first make this contract the owner by calling
    // transferOwnership from the current owner. Since the freshly deployed c has owner == deployer
    // (the checker deploys c and then deploys this test passing c), the test must first ensure
    // the test contract is owner by invoking transferOwnership only if needed. To do that we
    // attempt to call transferOwnership and ignore failure: if it succeeds, this contract becomes owner.
    // Then we call owned() and record whether it reverted. Finally we assert that the call reverted
    // iff c.owner() != address(this).
    function run(bool tryAcquire) public payable {
        // Optional: attempt to become owner. If we are already owner this may revert (onlyOwner),
        // so wrap in try/catch to continue.
        if (tryAcquire) {
            try c.transferOwnership(address(this)) {
                // succeeded -> now this contract is owner
            } catch {
                // failed -> likely because msg.sender (this contract) was not the owner; continue
            }
        }

        // Now attempt to call owned() and detect revert.
        bool reverted;
        try c.owned() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Observe current owner via public getter
        address currentOwner = c.owner();

        // General rule: owned() should revert exactly when this contract is NOT the owner.
        assert(reverted == (currentOwner != address(this)));
    }

    receive() external payable {}
}

