contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function
    function run(address initialOwner, address newOwner) public payable {
        require(initialOwner != address(0) && newOwner != address(0));

        // We must initialize c.owner to initialOwner. The test contract is msg.sender for calls on c.
        // Only the current owner can call transferOwnership, so first set owner to initialOwner by
        // having the contract that deployed c set owner. However, per the problem statement the
        // checker deploys a fresh c and this contract is the msg.sender for calls. We cannot
        // directly set c.owner except by calling transferOwnership when this contract is current owner.
        // So we first record the current owner (as deployed) and if it's not initialOwner, we try to
        // transfer ownership to initialOwner if and only if this contract is currently owner.

        address beforeOwner = c.owner();

        bool setToInitialReverted;
        if (beforeOwner == address(this)) {
            // we are currently owner, so we can transfer to initialOwner
            try c.transferOwnership(initialOwner) {
                setToInitialReverted = false;
            } catch {
                setToInitialReverted = true;
            }
        } else {
            // cannot change owner to initialOwner because we are not owner; mark as reverted
            setToInitialReverted = true;
        }

        address ownerAfterSetup = c.owner();

        // Now attempt the deciding call: try to transfer ownership to newOwner
        bool transferReverted;
        try c.transferOwnership(newOwner) {
            transferReverted = false;
        } catch {
            transferReverted = true;
        }

        address finalOwner = c.owner();

        // General rule to assert:
        // - If transferOwnership(newOwner) did not revert, then finalOwner == newOwner.
        // - If it reverted, then finalOwner == ownerAfterSetup (owner unchanged).
        assert((!transferReverted && finalOwner == newOwner) || (transferReverted && finalOwner == ownerAfterSetup));
    }

    receive() external payable { }
}

