contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function: take an address to set as owner (if current owner) and test owned()
    function run(address newOwner) public payable {
        // no precondition on newOwner

        // Read owner before any interactions
        address ownerBefore = c.owner();

        // Try to call transferOwnership to set up a state where this contract is owner or not.
        // Since the test contract is the deployer of c, it might or might not be owner; attempt and ignore revert.
        bool transferReverted;
        try c.transferOwnership(newOwner) {
            transferReverted = false;
        } catch {
            transferReverted = true;
        }

        // Read owner after the setup attempt
        address ownerAfterSetup = c.owner();

        // Now call owned() which is a function guarded by onlyOwner; capture whether it reverts
        bool ownedReverted;
        try c.owned() {
            ownedReverted = false;
        } catch {
            ownedReverted = true;
        }

        // Read owner after calling owned()
        address ownerAfter = c.owner();

        // General rule to assert for all inputs/executions:
        // 1) Calling owned() never changes owner (ownerAfter == ownerAfterSetup).
        // 2) owned() succeeds (does not revert) only when msg.sender == ownerAfterSetup; otherwise it reverts.
        // Since calls from this test are made with msg.sender == address(this), we check consistency.
        assert(ownerAfter == ownerAfterSetup && ((ownedReverted && address(this) != ownerAfterSetup) || (!ownedReverted && address(this) == ownerAfterSetup)));
    }

    receive() external payable { }
